class Solution {
    public int lengthOfLongestSubstring(String s) {
        Set<Character> seen = new HashSet<>();      // 窗口里的字符
        int l = 0, best = 0;
        for (int r = 0; r < s.length(); r++) {
            char ch = s.charAt(r);
            while (seen.contains(ch)) {             // 有重复，左端收缩
                seen.remove(s.charAt(l));
                l++;
            }
            seen.add(ch);
            best = Math.max(best, r - l + 1);
        }
        return best;
    }
}

