class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        last, left, best = {}, 0, 0
        for i, c in enumerate(s):
            if last.get(c, -1) >= left:     # c 在窗口里出现过
                left = last[c] + 1
            last[c] = i
            best = max(best, i - left + 1)
        return best

